// Google returns the star rating as a word. Normalise it, drop anything that
// already has a reply, and drop anything older than the lookback window so a
// first run against a long review history does not blast out 200 replies.
const WORD_TO_NUMBER = { ONE: 1, TWO: 2, THREE: 3, FOUR: 4, FIVE: 5 };
const lookbackDays = Number($('Config').first().json.reviewLookbackDays ?? 30);
const cutoff = Date.now() - lookbackDays * 24 * 60 * 60 * 1000;

const out = [];

for (const item of $input.all()) {
  for (const review of item.json.reviews ?? []) {
    if (review.reviewReply) continue;

    const createdAt = review.createTime ?? review.updateTime;
    if (createdAt && new Date(createdAt).getTime() < cutoff) continue;

    const rating = WORD_TO_NUMBER[review.starRating] ?? 0;

    out.push({
      json: {
        reviewId: review.reviewId,
        resourceName: review.name,
        reviewerName: review.reviewer?.displayName ?? 'Google user',
        starRating: rating,
        comment: review.comment ?? '',
        createdAt,
        // A bare star rating with no text still deserves a thank-you, but there
        // is nothing to respond to specifically.
        hasText: Boolean(review.comment && review.comment.trim()),
      },
    });
  }
}

return out;

