const review = $('Find Unanswered Reviews').item.json;
const res = $json;

function escalate(reason) {
  return { json: { ...review, reply: null, autoReply: false, escalationReason: reason } };
}

if (res.error) return escalate(`Anthropic API error: ${res.error.message ?? res.error.type}`);
if (res.stop_reason === 'refusal') return escalate('Model declined to draft a reply.');

const textBlock = (res.content ?? []).find((b) => b.type === 'text');
if (!textBlock) return escalate('No text block in the model response.');

let parsed;
try {
  parsed = JSON.parse(textBlock.text);
} catch (e) {
  return escalate(`Model output was not valid JSON: ${e.message}`);
}

// Belt and braces: the model self-reports, and we scan independently. Either
// signal sends the reply to a human instead of to Google.
const INSURANCE = /\b(insurance|insurer|claim|claims|adjuster|carrier|deductible|policy|coverage)\b/i;
if (parsed.mentions_insurance === true || INSURANCE.test(parsed.reply)) {
  return escalate('Drafted reply referenced insurance or claims — needs a human.');
}

if (parsed.reply.length > 400) {
  return escalate(`Drafted reply is ${parsed.reply.length} characters — too long for a review reply.`);
}

return { json: { ...review, reply: parsed.reply, autoReply: true, escalationReason: null } };

// Everything replied to is written to the CRM so the review history lives next
// to the job history rather than only in Google.
const draft = $('Vet the Draft').item.json;
const postResult = $json;

const posted = Boolean(postResult?.comment || postResult?.updateTime);

return {
  json: {
    id: draft.reviewId,
    reviewerName: draft.reviewerName,
    starRating: draft.starRating,
    comment: draft.comment,
    createdAt: draft.createdAt,
    replyText: posted ? draft.reply : undefined,
    authoredBy: 'automation',
    // A failed PUT is not a silent success — it lands in the CRM as escalated
    // so someone answers the review by hand.
    escalated: !posted,
    escalationReason: posted ? undefined : `Google rejected the reply: ${postResult?.error?.message ?? 'unknown error'}`,
  },
};

// Low-rated review, or a draft that failed vetting. No automated reply.
const review = $json;
return {
  json: {
    id: review.reviewId,
    reviewerName: review.reviewerName,
    starRating: review.starRating,
    comment: review.comment,
    createdAt: review.createdAt,
    escalated: true,
    escalationReason: review.escalationReason ?? `${review.starRating}-star review — a person should call this customer.`,
  },
};

